import{z as l,x as B,o as E,c as d,q as r,j as i,D as e,d as t,s as n,S as o}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"指令调度","description":"","frontmatter":{"title":"指令调度","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cg-instruction-scheduling.md","filePath":"cs/cg-instruction-scheduling.md","lastUpdated":1791063341000}'),A={name:"cs/cg-instruction-scheduling.md"};function c(h,a,p,D,_,u){const s=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=r('<h1 id="指令调度" tabindex="-1">指令调度 <a class="header-anchor" href="#指令调度" aria-label="Permalink to &quot;指令调度&quot;">​</a></h1><div class="epigraph"><p>调度器的自由来自依赖，不来自胆量：真依赖动不得，假依赖是名字的债，资源是每拍都要结清的账。</p><footer>—— 据 Hennessy and Gross, ACM TOPLAS, 1983；Fisher, ISCA, 1981 整理</footer></div><p><a href="/cs/cg-instruction-selection">上一课</a>把 IR 盖成机器指令，输出的每条指令自带延迟与端口占用表；本课排它们的次序。<a href="/cs/list-scheduling">表调度</a>给过块内的就绪表与优先级，<a href="/cs/software-pipelining">软件流水</a>给过跨迭代的模调度，<a href="/cs/critical-path-scheduling">关键路径</a>给过块内下界。缺的是两遍调度的分工——分配前与分配后各做一次，看到的是两个不同的依赖图。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>依赖分三类：真依赖（读到先前的写）、反依赖（先前的读被后来的写追上）、输出依赖（两次写抢同一个名字）。真依赖是程序语义，动不得；后两类是名字复用欠下的债。分配前的调度器看到的图几乎只有真依赖——SSA 的名字互不复用——自由度最大；分配之后物理寄存器号出现，反依赖与输出依赖才长出来。只调度一遍是常见错误：分配前调度不知道有多少物理寄存器，把区间拉得满图都是，<a href="/cs/cg-register-allocation-deep">分配</a>就被逼溢出；分配后不再调度，假依赖原样留给硬件——硬件<a href="/cs/register-renaming">重命名</a>能救一部分，救不了端口与队列的容量。</p>',5)),(E(),i(o,null,{default:e(()=>[n(s,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20W1%5B%22%E5%86%99%20r1%22%5D%20--%3E%7C%22%E7%9C%9F%E4%BE%9D%E8%B5%96%20RAW%EF%BC%9A%E5%8A%A8%E4%B8%8D%E5%BE%97%22%7C%20R1%5B%22%E8%AF%BB%20r1%22%5D%0A%20%20R1%20--%3E%7C%22%E5%8F%8D%E4%BE%9D%E8%B5%96%20WAR%EF%BC%9A%E6%8D%A2%E5%90%8D%E5%8F%AF%E6%B6%88%22%7C%20W2%5B%22%E5%86%99%20r1%EF%BC%88%E6%96%B0%E5%80%BC%EF%BC%89%22%5D%0A%20%20W1%20--%3E%7C%22%E8%BE%93%E5%87%BA%E4%BE%9D%E8%B5%96%20WAW%EF%BC%9A%E6%8D%A2%E5%90%8D%E5%8F%AF%E6%B6%88%22%7C%20W2%0A%20%20W2%20--%3E%20FIX%5B%22%E6%8D%A2%E5%90%8D%20%2F%20%E9%87%8D%E5%91%BD%E5%90%8D%E5%90%8E%E4%B8%A4%E6%9D%A1%E8%BE%B9%E6%B6%88%E5%A4%B1%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">术语翻译：三类依赖的英文缩写是 RAW（写后读，真依赖）、WAR（读后写，反依赖）、WAW（写后写，输出依赖）。判断口诀：涉及「值真的流动」的只有 RAW，另外两类只是两个操作恰好共用同一个名字，给其中一个改个名就散了。</span></p><h3 id="两遍分工" tabindex="-1">两遍分工 <a class="header-anchor" href="#两遍分工" aria-label="Permalink to &quot;两遍分工&quot;">​</a></h3><p>分配前的调度以延迟为主、压力为辅：把 load 尽早拉起、把用结果的指令贴近定义，同时给活跃值设一个启发式上限，越界就不再拉——上限的基准就是目标的物理寄存器数。分配后的调度以假依赖为主：同一物理寄存器的写序不能换，但无关的指令可以填空。两遍各自收尾，不求全局最优：全局问题没有实用的精确解，循环里由<a href="/cs/software-pipelining">模调度</a>逼近，直线代码里连逼近都靠启发式。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>资源模型与延迟表从<a href="/cs/target-description">目标描述</a>来：发射宽度、每个端口的吞吐、每类指令的延迟。延迟表本身是近似——手册给的是典型值，转发路径与缓存命中都在改它——调度器拿到的是一张会撒谎的地图，所以调度的收益天然有方差。跨块调度放大方差：把热路径拉成超块做推测执行，路径频度估准时收益最大，猜错时把没用的工作白做；trace scheduling（Fisher, 1981）为此而生，尾巴复制与谓词化是它的工程化。Bernstein–Rodeh 的全局调度把这套思想推广到无环的大区域：跨块移动指令，条件是移动不改变可观察行为。</p><p><span class="marginnote">数字实例：假设 load 延迟 5 拍、加法 1 拍。<code>add</code> 依赖刚发射的 <code>load</code> 时，中间还有 4 拍空窗——调度器的工作就是把 4 条无关指令填进去，填不满才空转。延迟表若把 load 写成 3 拍，这 2 拍的误判就是收益方差的来源。</span></p><p><span class="marginnote">直觉类比：真依赖像接力赛——没接到棒就是跑不了；反依赖与输出依赖像两名选手共用同一个更衣柜，给其中一人换个柜子（寄存器重命名）就互不妨碍。调度器能重排的只有「换柜子」那一类。</span></p><p><span class="marginnote">延迟槽是把调度当正确性问题的遗迹：MIPS R2000 的 load 有一拍延迟槽，编译器不填指令硬件就空转。深流水与乱序发射让填充从义务变成选择——今天的静态调度几乎只为性能服务。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2>',9)),(E(),i(o,null,{default:e(()=>[n(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEP%5B%22%E4%BE%9D%E8%B5%96%E5%9B%BE%EF%BC%9A%E7%9C%9F%E4%BE%9D%E8%B5%96%20%2B%20%E8%B5%84%E6%BA%90%E8%A1%A8%22%5D%20--%3E%20PRE%5B%22%E5%88%86%E9%85%8D%E5%89%8D%E8%B0%83%E5%BA%A6%EF%BC%9A%E5%BB%B6%E8%BF%9F%E4%BC%98%E5%85%88%20%2B%20%E5%8E%8B%E5%8A%9B%E4%B8%8A%E9%99%90%22%5D%0A%20%20PRE%20--%3E%20RA%5B%22%E5%AF%84%E5%AD%98%E5%99%A8%E5%88%86%E9%85%8D%22%5D%0A%20%20RA%20--%3E%20FALSED%5B%22%E5%81%87%E4%BE%9D%E8%B5%96%E5%87%BA%E7%8E%B0%EF%BC%9AWAR%20%2F%20WAW%22%5D%0A%20%20FALSED%20--%3E%20POST%5B%22%E5%88%86%E9%85%8D%E5%90%8E%E8%B0%83%E5%BA%A6%EF%BC%9A%E5%A1%AB%E7%A9%BA%20%2B%20%E6%B6%88%E5%81%87%E4%BE%9D%E8%B5%96%22%5D%0A%20%20POST%20--%3E%20EMIT%5B%22%E8%BE%93%E5%87%BA%E6%9C%80%E7%BB%88%E9%A1%BA%E5%BA%8F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p>两遍之间是又一处不动点：分配前调度改压力，压力逼分配溢出，溢出改写 IR，图变了又得再调度。工程上的止损是固定顺序、各做一遍，把「再优化一轮」留给少数热点函数。这也是调度启发式的容错远高于分配的原因：排错序最多少赚，溢出错才叫错。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>乱序核在硬件里做同构的事：发射队列按操作数就绪动态挑指令，静态调度的作用因此打折——但它管不了缓存未命中前的取数次序，也管不了功耗。VLIW 是另一个极端：硬件不挑，调度器必须完美，<a href="/cs/target-description">目标描述</a>的精度直接变成正确性约束。本课不重讲块内表调度的步骤，不展开模调度的资源与迭代下界计算，两者各有先修课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>依赖三类：真依赖是语义，反依赖与输出依赖是名字复用的债。</li><li>分配前后各调度一遍：前者管延迟与压力上限，后者消假依赖、填发射空隙。</li><li>资源与延迟来自目标描述；延迟表是近似，收益有方差。</li><li>调度与分配互为不动点：排错序是损失，溢出错才是错。</li><li>出处：Hennessy and Gross, 1983；Fisher, 1981；Bernstein and Rodeh, 1991；Muchnick, 1997。</li></ul>',5))])}const g=l(A,[["render",c]]);export{m as __pageData,g as default};
